import hashlib
from pathlib import Path
import tempfile
import unittest
from unittest.mock import patch

import categories
import api_server
import config
import database
import starter_catalogue


class StarterCatalogueTests(unittest.TestCase):
    """Use only disposable files and synthetic public activity labels."""

    def setUp(self):
        """Build a small valid public seed and a separate pristine working schema."""
        temporary = tempfile.TemporaryDirectory(prefix='weekwise-starter-test-')
        self.addCleanup(temporary.cleanup)
        self.directory = Path(temporary.name)
        self.seed_path = self.directory / 'public.sqlite'
        self.target_path = self.directory / 'working.sqlite'
        self.seed = database.get_connection(self.seed_path)
        self.addCleanup(self.seed.close)
        database.init_db(self.seed)
        categories.seed_categories(self.seed, categories.load_taxonomy())
        bundle = self.seed.execute('SELECT id FROM bundles WHERE key=?',
                                    ('sports_racket',)).fetchone()[0]
        source_url = (config.UNISPORT_SCHEDULE_API_URL
                      + '?startDateMin=2026-11-16&startDateMax=2026-11-22'
                      + '&showBookingsFull=true&showCourses=true')
        with self.seed:
            self.seed.execute('''INSERT INTO series
                (id,source,external_id,title,description,organizer,bundle_id,sport,
                 location_type,source_url,is_recurring)
                VALUES (17,'unisport','history-pattern:1','Tennis - Level 1',
                        ?,'Unisport HSG',?,'Tennis - Level 1','tba',?,1)''',
                (config.TRAINING_CATALOGUE_DESCRIPTION, bundle,
                 config.UNISPORT_PUBLIC_SCHEDULE_URL))
            self.seed.execute('''INSERT INTO events
                (id,series_id,start_time,end_time,end_is_estimated,status)
                VALUES (71,17,'2026-11-16 07:00:00','2026-11-16 08:00:00',0,'unknown')''')
            self.seed.execute('''INSERT INTO events
                (id,series_id,start_time,end_time,end_is_estimated,status)
                VALUES (72,17,'2026-11-23 07:00:00','2026-11-23 08:30:00',1,'unknown')''')
            self.seed.execute('''INSERT INTO event_provenance
                (event_id,kind,forecast_anchor_date,evidence_weeks,created_at,
                 verification_url,verified_at)
                VALUES (71,'website','2026-11-06',3,'2026-11-15 09:00:00',
                        ?,'2026-11-15 10:00:00')''', (source_url,))
            self.seed.execute('''INSERT INTO event_provenance
                (event_id,kind,forecast_anchor_date,evidence_weeks,created_at)
                VALUES (72,'projected','2026-11-06',3,'2026-11-15 09:00:00')''')
            settings = (('catalogue_id', 'reviewed-synthetic-fixture'),
                        ('catalogue_mode', config.REVIEWED_CATALOGUE_MODE), ('setup_done', '1'))
            self.seed.executemany('INSERT INTO app_settings (key,value) VALUES (?,?)', settings)
        self.target = database.get_connection(self.target_path)
        self.addCleanup(self.target.close)
        database.init_db(self.target)

    def bootstrap(self, **arguments):
        """Use an explicit synthetic seed so tests never read a real published file."""
        return starter_catalogue.bootstrap_starter(
            self.target, self.seed_path, enabled=arguments.get('enabled', True))

    def snapshot(self, connection):
        """Read all SQL values and schema for exact non-mutation assertions."""
        return list(connection.iterdump())

    def test_fresh_schema_receives_ids_provenance_and_no_private_rows(self):
        """A pristine file receives the reviewed dataset with exact identities and evidence."""
        self.assertTrue(self.bootstrap())
        self.assertEqual(database.get_catalogue_id(self.target), 'reviewed-synthetic-fixture')
        self.assertEqual(database.get_provenance_counts(self.target),
                         {'website': 1, 'projected': 1, 'unspecified': 0})
        rows = self.target.execute('SELECT id,status FROM events ORDER BY id').fetchall()
        self.assertEqual([tuple(row) for row in rows], [(71, 'unknown'), (72, 'unknown')])
        self.assertFalse(any(self.target.execute(starter_catalogue.PRIVATE_COUNTS_SQL).fetchone()))
        self.assertEqual(self.target.execute('PRAGMA integrity_check').fetchone()[0], 'ok')
        self.assertFalse(self.target.execute('PRAGMA foreign_key_check').fetchall())

    def test_empty_database_file_needs_no_preexisting_schema(self):
        """API-first file creation can bootstrap before any application tables exist."""
        empty = database.get_connection(self.directory / 'empty.sqlite')
        self.addCleanup(empty.close)
        self.assertTrue(starter_catalogue.bootstrap_starter(empty, self.seed_path, enabled=True))
        self.assertEqual(empty.execute('SELECT COUNT(*) FROM events').fetchone()[0], 2)

    def test_api_first_start_serves_the_same_reviewed_file(self):
        """The API startup hook must seed a fresh file before any Streamlit visit."""
        with patch.object(config, 'PUBLIC_UNISPORT_SEED', self.seed_path), \
                patch.object(config, 'USE_PUBLIC_STARTER', True):
            api_server.prepare_database(self.target_path)
        client = api_server.create_app(self.target_path).test_client()
        response = client.get('/events', query_string={'from': '2026-11-16',
                                                       'to': '2026-11-24'})
        self.assertEqual(response.status_code, 200)
        self.assertEqual(len(response.json), 2)
        self.assertEqual(response.headers[config.API_CATALOGUE_HEADER],
                         'reviewed-synthetic-fixture')
        self.assertEqual({row['provenance_kind'] for row in response.json},
                         {'website', 'projected'})

    def test_replay_preserves_profile_manual_edits_and_immutable_seed(self):
        """Once copied, subsequent starts never replace local people or manual changes."""
        original = hashlib.sha256(self.seed_path.read_bytes()).hexdigest()
        self.assertTrue(self.bootstrap())
        database.create_user(self.target, 'Alex')
        with self.target:
            self.target.execute('UPDATE series SET title=? WHERE id=?', ('Local correction', 17))
        before = self.snapshot(self.target)
        self.assertFalse(self.bootstrap())
        self.assertEqual(self.snapshot(self.target), before)
        self.assertEqual(hashlib.sha256(self.seed_path.read_bytes()).hexdigest(), original)

    def test_existing_profile_is_never_replaced(self):
        """An earlier local profile blocks public seeding even before course rows exist."""
        database.create_user(self.target, 'Alex')
        before = self.snapshot(self.target)
        self.assertFalse(self.bootstrap())
        self.assertEqual(self.snapshot(self.target), before)

    def test_explicit_demo_reset_does_not_switch_to_the_public_catalogue(self):
        """Resetting a demo keeps that choice even when the released starter is present."""
        database.create_user(self.target, 'Alex')
        database.reset_database(self.target)
        self.assertEqual(database.get_setting(self.target, 'catalogue_mode'),
                         config.DEFAULT_CATALOGUE_ID)
        self.assertFalse(self.bootstrap())
        self.assertEqual(self.target.execute('SELECT COUNT(*) FROM events').fetchone()[0], 0)

    def test_existing_settings_and_archive_imports_are_preserved(self):
        """Settings and source metadata each identify an occupied target, not an empty app."""
        for statement, params in (
                ('INSERT INTO app_settings (key,value) VALUES (?,?)', ('keep', 'local')),
                ('''INSERT INTO training_imports
                    (file_name,source_fingerprint,imported_at) VALUES (?,?,?)''',
                 ('private-fixture.csv', 'synthetic-hash', '2026-11-15 09:00:00'))):
            with self.subTest(statement=statement):
                with self.target:
                    self.target.execute(statement, params)
                before = self.snapshot(self.target)
                self.assertFalse(self.bootstrap())
                self.assertEqual(self.snapshot(self.target), before)

    def test_unrelated_database_schema_is_not_overwritten(self):
        """Even an empty unrelated table belongs to its existing database owner."""
        other = database.get_connection(self.directory / 'other.sqlite')
        self.addCleanup(other.close)
        with other:
            other.execute('CREATE TABLE unrelated (value TEXT)')
        before = self.snapshot(other)
        self.assertFalse(starter_catalogue.bootstrap_starter(other, self.seed_path, enabled=True))
        self.assertEqual(self.snapshot(other), before)

    def test_missing_disabled_and_in_memory_targets_remain_unchanged(self):
        """Explicit demo mode, isolated test paths and memory fixtures do not load public data."""
        before = self.snapshot(self.target)
        self.assertFalse(self.bootstrap(enabled=False))
        self.assertFalse(starter_catalogue.bootstrap_starter(
            self.target, self.directory / 'missing.sqlite', enabled=True))
        memory = database.get_connection(':memory:')
        self.addCleanup(memory.close)
        database.init_db(memory)
        self.assertFalse(starter_catalogue.bootstrap_starter(memory, self.seed_path, enabled=True))
        self.assertEqual(memory.execute('SELECT COUNT(*) FROM events').fetchone()[0], 0)
        self.assertEqual(self.snapshot(self.target), before)

    def test_configuration_switch_is_read_at_call_time(self):
        """Configured demo isolation can override the default without stale bound arguments."""
        with patch.object(config, 'PUBLIC_UNISPORT_SEED', self.seed_path), \
                patch.object(config, 'USE_PUBLIC_STARTER', False):
            self.assertFalse(starter_catalogue.bootstrap_starter(self.target))
        with patch.object(config, 'PUBLIC_UNISPORT_SEED', self.seed_path), \
                patch.object(config, 'USE_PUBLIC_STARTER', True):
            self.assertTrue(starter_catalogue.bootstrap_starter(self.target))

    def test_seed_with_user_data_is_rejected_before_any_copy(self):
        """A mistakenly chosen populated runtime database cannot become a public starter."""
        database.create_user(self.seed, 'Alex')
        before = self.snapshot(self.target)
        with self.assertRaises(ValueError):
            self.bootstrap()
        self.assertEqual(self.snapshot(self.target), before)

    def test_invalid_or_private_course_fields_are_rejected(self):
        """The selected public-course whitelist prevents accidental private-field copying."""
        with self.seed:
            self.seed.execute('UPDATE series SET description=? WHERE id=?',
                              ('Unreviewed private draft', 17))
        before = self.snapshot(self.target)
        with self.assertRaises(ValueError):
            self.bootstrap()
        self.assertEqual(self.snapshot(self.target), before)

    def test_invalid_event_availability_and_url_are_rejected(self):
        """Published occurrence provenance cannot legitimize an invented open booking or URL."""
        before = self.snapshot(self.target)
        with self.seed:
            self.seed.execute('UPDATE events SET status=? WHERE id=?', ('open', 71))
        with self.assertRaises(ValueError):
            self.bootstrap()
        with self.seed:
            self.seed.execute('UPDATE events SET status=? WHERE id=?', ('unknown', 71))
            self.seed.execute('UPDATE event_provenance SET verification_url=? WHERE event_id=?',
                              ('https://example.invalid/private-draft', 71))
        with self.assertRaises(ValueError):
            self.bootstrap()
        self.assertEqual(self.snapshot(self.target), before)

    def test_unexpected_schema_object_and_corrupt_file_are_rejected(self):
        """Extra source behavior and unreadable database content never produce a demo fallback."""
        with self.seed:
            self.seed.execute('CREATE VIEW unexpected AS SELECT id FROM series')
        before = self.snapshot(self.target)
        with self.assertRaises(ValueError):
            self.bootstrap()
        invalid = self.directory / 'invalid.sqlite'
        invalid.write_bytes(b'This is not a SQLite database.')
        with self.assertRaises(ValueError):
            starter_catalogue.bootstrap_starter(self.target, invalid, enabled=True)
        self.assertEqual(self.snapshot(self.target), before)

    def test_hidden_source_columns_and_custom_target_schema_are_preserved(self):
        """Whole-file backup must not copy hidden columns or discard custom target DDL."""
        with self.seed:
            self.seed.execute('ALTER TABLE series ADD COLUMN private_draft TEXT')
            self.seed.execute('UPDATE series SET private_draft=? WHERE id=?',
                              ('Synthetic private value', 17))
        before = self.snapshot(self.target)
        with self.assertRaises(ValueError):
            self.bootstrap()
        self.assertEqual(self.snapshot(self.target), before)
        with self.target:
            self.target.execute('ALTER TABLE series ADD COLUMN local_extension TEXT')
        custom = self.snapshot(self.target)
        self.assertFalse(self.bootstrap())
        self.assertEqual(self.snapshot(self.target), custom)

    def test_same_file_and_pending_target_transaction_are_rejected(self):
        """The immutable source cannot serve as the target or commit a caller's pending work."""
        with self.assertRaises(ValueError):
            starter_catalogue.bootstrap_starter(self.seed, self.seed_path, enabled=True)
        self.target.execute('INSERT INTO app_settings (key,value) VALUES (?,?)', ('pending', '1'))
        with self.assertRaises(ValueError):
            self.bootstrap()
        self.assertTrue(self.target.in_transaction)
        self.target.rollback()
        self.assertEqual(self.target.execute('SELECT COUNT(*) FROM events').fetchone()[0], 0)
